bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
stage=deploy/state/help-rich-manual-20261123
test -s deploy/state/help-rich-manual-live-20261123.json
test -s "$stage/checkpoint.json"
target_sha="$(python3 -c 'import json;print(json.load(open("deploy/state/help-rich-manual-20261123/checkpoint.json"))["new_sha"])')"
test "$(docker exec deploy-gaybbs-1 sha256sum /app/gaybbs.mjs|cut -d' ' -f1)" = "$target_sha"
test "$(docker inspect -f '{{.State.Running}}' deploy-gaybbs-1)" = true
test "$(docker inspect -f '{{.State.Restarting}}' deploy-gaybbs-1)" = false
test "$(docker inspect -f '{{.State.Running}}' deploy-postgres-1)" = true
test "$(systemctl --user is-active gace-userbot-verify.service)" = active
docker exec deploy-gaybbs-1 node -e '
const s=require("fs").readFileSync("/app/gaybbs.mjs","utf8");
const a=s.indexOf("function registerOperationHelpHandlers("),b=s.indexOf("// src/",a+8),t=s.slice(a,b<0?s.length:b);
const h=s.indexOf("// src/bot/operationHelpHandlers.ts"),j=s.indexOf("// src/",h+7),section=s.slice(h,j<0?s.length:j);
const needed=["sectionText","HTML","profile","room","announcement","link","search","help:open:","help:home:"];
for(const k of needed)if(!section.includes(k))process.exit(71);
if(!t.includes("startCompactProfileEditor"))process.exit(72);
if(!s.includes("STARTLESS_REPEATED_START_LINK_FORBIDDEN"))process.exit(73);
if(section.length<5000)process.exit(74);
console.log("GAYBBS_HELP_LIVE_RICH_AND_FIVE_TOPICS=PASS");
'
test "$(systemctl --user is-enabled gace-userbot-verify.service)" = enabled
python3 -B scripts/userbot_test_client.py health >/dev/null
test "$(systemctl --user is-active gace-userbot-verify.service)" = active
echo GAYBBS_HELP_INDEPENDENT_READBACK=PASS
echo USERBOT_RESIDENT_IPC_HEALTH=PASS
